import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";import"./chunks/assets.NJs4UO-Q.js";var i=JSON.parse(`{"title":"Kimi Code 社区倡议","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code/community-guidelines.md","filePath":"zh/kimi-code/community-guidelines.md"}`),a={name:`kimi-code/community-guidelines.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="kimi-code-社区倡议" tabindex="-1">Kimi Code 社区倡议 <a class="header-anchor" href="#kimi-code-社区倡议" aria-label="Permalink to “Kimi Code 社区倡议”">​</a></h1><p>Kimi Code 致力于为全球用户提供智能、高效的 AI 编程服务，用模型能力的持续跃迁、Agent产品力的极致打磨、Token Plan的范式革新，缩短人类想象到现实的路径，让通用agent普惠每个有想法的个体。为保证每位Kimi Code用户拥有更好的体验，我们提出以下倡议。</p><h2 id="适用范围" tabindex="-1">适用范围 <a class="header-anchor" href="#适用范围" aria-label="Permalink to “适用范围”">​</a></h2><p>Kimi Code 订阅仅限交互式使用，我们兼容主流编程工具与 Agent 框架（Kimi CLI、VS Code、Claude Code、OpenCode、OpenClaw 等），你可以在自己习惯的工具里自由调用 Kimi Code 的 AI 能力。如有企业级集成、商业化服务或其他开放平台相关需求，也可前往 <a href="https://platform.moonshot.cn" target="_blank" rel="noreferrer">Kimi 开放平台</a> 了解更多合作方案。</p><h2 id="✧-我们有必要提示的使用规范" tabindex="-1"><span style="opacity:0.5;font-size:0.85em;margin-right:4px;">✧</span> 我们有必要提示的使用规范 <a class="header-anchor" href="#✧-我们有必要提示的使用规范" aria-label="Permalink to “✧ 我们有必要提示的使用规范”">​</a></h2><p>为了让每个人都能持续获得稳定的模型服务，有一些使用规范我们需要大家一起遵守。</p><div class="community-guidelines"><div class="guideline-grid"><div class="guideline-card"><h4>不以商业化为目的转售账号或 API 访问权限</h4><p>账号是你和 Kimi Code 之间的连接，转让给他人使用也会让你自己的数据和使用记录处于风险中。</p></div><div class="guideline-card"><h4>不将 Kimi Code 的能力以任何形式二次分售</h4><p>用 Kimi Code 来辅助自己的工作完全没问题，但把它包装成服务再卖给别人，绕过平台的定价和服务体系，对其他正常用户也不公平。</p></div><div class="guideline-card"><h4>不伪造或篡改客户端身份信息</h4><p>客户端身份信息是平台识别请求来源、保障服务质量与安全的重要依据，伪造 User-Agent 或使用高风险的 Agent 不利于平台维护整体服务的稳定性。</p></div><div class="guideline-card"><h4>不进行非个人交互式使用</h4><p>Kimi Code 订阅仅限个人交互式使用场景。通过脚本批量执行、数据标注等非交互式方式使用，超出了正常使用范畴。</p></div></div></div><p>如果出现了不符合上述规范的使用方式，我们会先评估情况，再根据情节进行<strong>暂停访问</strong>等处理。你会收到 <code>Access terminated</code> 报错，详情请见<a href="/code/docs/kimi-code/error-reference.html#账号访问终止">错误参考文档</a>。相应地，若用户通过非官方渠道获取服务（如账号转售、第三方代购等），一经核实可能面临封号处理，且由此产生的损失需由用户<strong>自行承担</strong>。</p><div class="warning custom-block"><p class="custom-block-title">处理有误？</p><p>若你被错误封禁，请通过支持邮箱联系我们 <a href="mailto:support@moonshot.cn" target="_blank" rel="noreferrer">support@moonshot.cn</a>。为了更好地帮你解决问题，请务必提交账号 ID、封禁时间、使用场景说明及证明截图。</p></div><h2 id="♡-我们欢迎的使用方式" tabindex="-1"><span style="opacity:0.5;font-size:0.85em;margin-right:4px;">♡</span> 我们欢迎的使用方式 <a class="header-anchor" href="#♡-我们欢迎的使用方式" aria-label="Permalink to “♡ 我们欢迎的使用方式”">​</a></h2><p>Kimi Code 欢迎每一位用代码改变世界的创造者——无论你是独立开发者、开源贡献者、还是正在把第一个想法变成产品的新手。我们更鼓励持续专注的使用方式，对于保持长会话、并充分复用历史内容的用户，平台会动态优化其额度使用效率，即在相同工作量下额度更加耐用。</p><h2 id="加入社区" tabindex="-1">加入社区 <a class="header-anchor" href="#加入社区" aria-label="Permalink to “加入社区”">​</a></h2><p>如果你想和更多志同道合的 Kimi Coder 交流技术心得，欢迎加入我们的飞书交流群，一起 Happy Coding！</p><div style="display:flex;justify-content:center;"><img src="/code/docs/images/zh/kimi-code/contact-and-feedback/feishu-group.png" alt="Kimi Code 用户群飞书二维码" style="max-width:280px;width:100%;border-radius:8px;"></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h2><p><strong>Q1: 我是重度用户，每天高强度使用，会被误封吗？</strong></p><p>不会。风控识别会考虑多种特征，对于 IP 地址、对话状态等使用指标正常的重度用户通常不会触发处置。</p><p><strong>Q2：我用 VPN 或公司代理访问，会被误封吗？</strong></p><p>通过代理访问 Kimi（正向代理）没问题；把自己的账号给别人转发（反向代理），属于违规。</p><p><strong>Q3: 我同时在多个设备或工具上使用 Kimi Code，会被误封吗？</strong></p><p>不会。开发者在不同设备（如工作电脑、个人笔记本）或使用不同编程工具（Kimi CLI、VS Code、Claude Code）之间切换，属于完全正常的使用模式。只要不刻意篡改客户端身份信息就不会被误封。</p>`,21)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};